/// <summary>
/// The <c>AVAWHSProcessGuidePromptLicensePlateIdPageBuilder</c> builds a page for ask the new License plate id
/// </summary>
[
    ProcessGuidePageBuilderName(classStr(AVAWHSProcessGuidePromptLicensePlateIdPageBuilder))
]
class AVAWHSProcessGuidePromptLicensePlateIdPageBuilder extends ProcessGuidePageBuilder
{
}

Method.Source:
protected final void addDataControls(ProcessGuidePage _page)
{
    WhsrfPassthrough pass;

    pass = controller.parmSessionState().parmPass();

    _page.addLabel(
            ProcessGuideDataTypeNames::Scan,
            "@WAX722",
            extendedTypeNum(WHSRFUndefinedDataType));

    _page.addTextBox(
        ProcessGuideDataTypeNames::AVALicensePlateId,
            "@WAX359",
            extendedTypeNum(WHSLicensePlateId));
}

protected final void addActionControls(ProcessGuidePage _page)
{
    #ProcessGuideActionNames

    _page.addButton(step.createAction(#ActionOK), true);
    _page.addButton(step.createAction(#ActionCancelResetProcess), false, "@SYS16512");
    _page.addButton(step.createAction(#ActionCancelExitProcess));
}
